import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { OrderService } from 'src/app/data/service/order/order.service';
import { GAccount } from '../../../../core/common/GAccount';
import { CourseService } from '../../../../data/service/course/course.service';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { G } from '../../../../core/common/G';
import { Urls } from '../../../../core/common/Urls';

@Component({
  selector: 'app-page404',
  templateUrl: './page404.component.html',
  styleUrls: ['./page404.component.scss']
})
export class Page404Component implements OnInit {

  queryText = '';
  showSearchbar = false;
  payState = false;

  constructor(
    private courseService: CourseService,
    private orderService: OrderService,
    private router: Router,
    public toastController: ToastController,
    public loadingController: LoadingController
  ) {
  }

  ngOnInit(): void {

  }

  ionViewWillEnter() {

    this.payState = G.IsPhonePayState;

    if (GAccount.IsLoggedIn() && G.IsPhonePayState) {

      SharedIonic.loading(this.loadingController);

      this.courseService.GetUserCoursesId().subscribe(
        res => {
          G.IsPhonePayState = false;
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            GResponse.MyCourseIds = res.data;
          } else {
            GResponse.MyCourseIds = [];
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          G.IsPhonePayState = false;
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );

      this.orderService.GetUserCart().subscribe(
        res => {
          G.IsPhonePayState = false;
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            if (res.data.courses == null) {
              GResponse.setCartCoursesCount(0);
              this.router.navigateByUrl(Urls.HomeUrl);
            } else {
              GResponse.setCartCoursesCount(res.data.courses.length);
              this.router.navigateByUrl(Urls.HomeUrl);
            }
          } else {
            GResponse.setCartCoursesCount(0);
            this.router.navigateByUrl(Urls.HomeUrl);
          }
        },
        err => {
          G.IsPhonePayState = false;
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
          this.router.navigateByUrl(Urls.HomeUrl);
        }
      );
      G.IsPhonePayState = false;
    }
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

}
